// ── n8n Code node: "Build Agent Query" ───────────────────────────────────────
// Runs after Patch Lead (success). Resolves the Lead Id from Prep Patch and
// builds a SOQL query for the assigned owner. TYPEOF handles the case where the
// lead is owned by a queue (Group) instead of a User without erroring.
const patchUrl = $('Prep Patch').item.json.patchUrl || '';
const id = String(patchUrl).split('/').pop();

const soql =
  "SELECT Id, TYPEOF Owner " +
  "WHEN User THEN Name, Title, Email, Phone, MobilePhone, Personal_Cell_Phone_Number__c, Headshot_Photo__c, User_Photo_URL__c " +
  "ELSE Name END " +
  "FROM Lead WHERE Id='" + id + "' LIMIT 1";

const agentUrl =
  'https://bigthink.my.salesforce.com/services/data/v60.0/query/?q=' + encodeURIComponent(soql);

return { agentUrl };

// ── n8n Code node: "Shape Agent" ─────────────────────────────────────────────
// Shapes the assigned owner (only when it's a User) into the compact agent
// payload the landing page renders on the success screen. Returns agent: null
// for queue-owned leads or if the lookup returned nothing.
const recs = Array.isArray($json.records) ? $json.records : [];
const o = recs.length ? recs[0].Owner : null;

let agent = null;
if (o && o.attributes && o.attributes.type === 'User') {
  agent = {
    name: o.Name || null,
    title: o.Title || null,
    email: o.Email || null,
    phone: o.Phone || o.Personal_Cell_Phone_Number__c || o.MobilePhone || null,
    photoUrl: o.Headshot_Photo__c || o.User_Photo_URL__c || null,
  };
}

return { agent };
